    longDescription: `
      <p>شفرة B201 102 A01 أحادية الحافة مصممة لتطبيقات الكشط والقطع الصناعي. مصنوعة من الفولاذ الكربوني العالي ومعالجة حرارياً في أجواء متحكم بها للوصول إلى صلابة HRC 58-62.</p>

      <h3>ملف شحذ 2-فاسيت</h3>
      <p>ملف الشحذ 2-فاسيت (ثنائي السطح) يوفر <strong>توازناً مثالياً بين المتانة والحدة</strong>. يُفضل هذا الملف في الكشط العام وتنظيف الأسطح وعمليات القطع. مقارنة بـ 3-فاسيت، يوفر عمر حافة أطول وأداء موثوق حتى على الأسطح الصلبة.</p>

      <h3>مجالات الاستخدام</h3>
      <ul>
        <li><strong>صناعة الزجاج:</strong> كشط أسطح الزجاج، إزالة الملصقات والاستيكرات، تنظيف الزجاج</li>
        <li><strong>السيارات:</strong> إزالة نتوءات المطاط، كشط الحشوات، إزالة أفلام الزجاج</li>
        <li><strong>البناء:</strong> كشط الدهان والمعجون، تحضير الأسطح</li>
        <li><strong>الطباعة والتغليف:</strong> كشط الحبر، تنظيف البكرات</li>
      </ul>

      <h3>التفاصيل التقنية</h3>
      <p>تصميم غلاف الألومنيوم يوفر نقل وتخزين آمن. الحافة المحززة تمكّن من التركيب المتوافق مع أدوات الكشط القياسية. تم تطبيق معالجة سطحية مقاومة للتآكل.</p>
    `,
